CREATE UNIQUE INDEX "AccountingWork_fulfillment_original_key" ON "AccountingWork" USING btree ("organizationId","entityInstanceId","effectKind") WHERE "operation" = 'original' AND "effectKind" IN ('fulfillment_accounting', 'customer_credit_issued', 'invoice_issued', 'payout_settlement', 'expense_bill', 'vendor_bill_matched', 'inventory_receipt');--> statement-breakpoint
CREATE UNIQUE INDEX "AccountingWork_money_original_key" ON "AccountingWork" USING btree ("organizationId","moneyTransactionId","effectKind") WHERE "operation" = 'original' AND "effectKind" IN ('customer_receipt', 'customer_refund');--> statement-breakpoint
ALTER TABLE "AccountingWork" ADD CONSTRAINT "AccountingWork_kind_check" CHECK (("AccountingWork"."effectKind" IN ('fulfillment_accounting', 'customer_credit_issued', 'invoice_issued', 'invoice_write_off', 'payout_settlement', 'expense_bill', 'vendor_bill_matched', 'inventory_receipt') AND "AccountingWork"."entityInstanceId" IS NOT NULL AND "AccountingWork"."moneyTransactionId" IS NULL) OR ("AccountingWork"."effectKind" IN ('customer_receipt', 'customer_refund', 'deposit_application') AND "AccountingWork"."moneyTransactionId" IS NOT NULL AND "AccountingWork"."entityInstanceId" IS NULL));